#!/usr/bin/env bash
set -eo pipefail
# Generated by the configuration under test, not a source file in this repo.
# shellcheck source=/dev/null
source "$HOME/.profile"
# Managed tools precede unmanaged ~/.local/bin copies; unmanaged-only tools still resolve.
for tool in python python3 node uv rtk; do
  resolved=$(command -v "$tool")
  if [[ "$resolved" == "$HOME/.local/bin/"* ]]; then
    printf 'ERROR: %s resolves to unmanaged %s\n' "$tool" "$resolved" >&2
    exit 1
  fi
done
if [[ -e "$HOME/.local/bin/only-unmanaged" ]]; then
  test "$(only-unmanaged)" = unmanaged-ok
fi
python3 -c 'import sys; print(sys.executable)' | grep -q "$HOME/.local/share/mise/installs/python/"
python - <<'PY'
from pathlib import Path
import subprocess
import sys
import tomllib
tools = tomllib.loads((Path.home() / '.config/mise/config.toml').read_text())['tools']
assert sys.version_info[:3] == tuple(map(int, tools['python'].split('.'))), sys.version
assert subprocess.check_output(['node', '--version'], text=True).strip() == 'v' + tools['node']
interpreter = Path(sys.executable).resolve()
assert interpreter.is_relative_to(Path.home() / '.local/share/mise/installs/python'), interpreter
uv_interpreter = subprocess.check_output(
    ['uv', 'run', '--no-project', 'python', '-c', 'import sys; print(sys.executable)'], text=True
).strip()
assert Path(uv_interpreter).resolve() == interpreter, (interpreter, uv_interpreter)
print('Verified Node', tools['node'], 'and mise/uv Python', tools['python'])
PY
